-- Plan « Puissance max en aéro 12 semaines » (12 semaines) : 45 séances,
-- objectif aéro et indicateur de réussite (passages en TT validés) par séance.
-- Textes en 9 langues assemblés depuis des gabarits par type. Rejouable.

WITH tpl(typ, lang, name, obj, info) AS (VALUES

('e_cont', 'fr', 'Endurance TT {n}×{d}', 'Objectif physiologique : Développer l''endurance fondamentale et la base aérobie. Objectif aéro : Tenir la position TT en endurance (65-72 % FTP), sans se relever pendant les blocs.', 'Endurance fondamentale en position TT : intensité facile pour que toute l''attention aille à la tenue (tête basse, épaules relâchées, appui stable). Les blocs s''allongent d''une semaine à l''autre.'),
('e_cont', 'en', 'TT endurance {n}×{d}', 'Physiological goal: Build base endurance and your aerobic base. Aero goal: Hold the TT position at endurance pace (65-72% FTP) without sitting up during the blocks.', 'Base endurance in the TT position: easy intensity so all your attention goes to holding it (head low, shoulders relaxed, stable support). The blocks get longer every week.'),
('e_cont', 'es', 'Resistencia TT {n}×{d}', 'Objetivo fisiológico: Desarrollar la resistencia básica y la base aeróbica. Objetivo aero: Mantener la posición TT a ritmo de resistencia (65-72 % FTP) sin incorporarte en los bloques.', 'Resistencia básica en posición TT: intensidad suave para que toda la atención vaya a mantenerla (cabeza baja, hombros relajados, apoyo estable). Los bloques se alargan cada semana.'),
('e_cont', 'it', 'Resistenza TT {n}×{d}', 'Obiettivo fisiologico: Sviluppare la resistenza di base e la base aerobica. Obiettivo aero: Tenere la posizione TT a ritmo di resistenza (65-72 % FTP) senza rialzarti nei blocchi.', 'Resistenza di base in posizione TT: intensità facile perché l''attenzione vada tutta alla tenuta (testa bassa, spalle rilassate, appoggio stabile). I blocchi si allungano ogni settimana.'),
('e_cont', 'de', 'TT-Ausdauer {n}×{d}', 'Physiologisches Ziel: Grundlagenausdauer und aerobe Basis entwickeln. Aero-Ziel: Die TT-Position im Grundlagentempo (65-72 % FTP) halten, ohne dich in den Blöcken aufzurichten.', 'Grundlagenausdauer in TT-Position: leichte Intensität, damit die ganze Aufmerksamkeit dem Halten gilt (Kopf tief, Schultern locker, stabile Auflage). Die Blöcke werden jede Woche länger.'),
('e_cont', 'nl', 'TT-duur {n}×{d}', 'Fysiologisch doel: Basisduur en je aerobe basis ontwikkelen. Aerodoel: De TT-houding vasthouden op duurtempo (65-72 % FTP) zonder overeind te komen tijdens de blokken.', 'Basisduur in TT-houding: lichte intensiteit zodat al je aandacht naar het vasthouden gaat (hoofd laag, schouders ontspannen, stabiele steun). De blokken worden elke week langer.'),
('e_cont', 'pt', 'Resistência TT {n}×{d}', 'Objetivo fisiológico: Desenvolver a resistência de base e a base aeróbia. Objetivo aero: Manter a posição TT em ritmo de resistência (65-72 % FTP) sem levantar o tronco nos blocos.', 'Resistência de base na posição TT: intensidade leve para que toda a atenção vá para mantê-la (cabeça baixa, ombros relaxados, apoio estável). Os blocos ficam mais longos a cada semana.'),
('e_cont', 'ja', 'TT持久 {n}×{d}', '生理学的目標：基礎持久力と有酸素ベースを伸ばす。 エアロ目標：持久ペース（65〜72 % FTP）でTTポジションを保ち、ブロック中は起き上がらない。', 'TTポジションでの基礎持久力：強度は楽にして保つことに集中（頭を低く、肩の力を抜き、安定した支え）。ブロックは週ごとに長くなります。'),
('e_cont', 'tr', 'TT dayanıklılık {n}×{d}', 'Fizyolojik hedef: Temel dayanıklılığı ve aerobik temeli geliştirmek. Aero hedefi: Dayanıklılık temposunda (%65-72 FTP) TT pozisyonunu koru, bloklarda doğrulma.', 'TT pozisyonunda temel dayanıklılık: tüm dikkatin pozisyonu korumakta olsun diye kolay yoğunluk (baş aşağıda, omuzlar gevşek, sabit destek). Bloklar her hafta uzar.'),
('s_3030', 'fr', '30/30 TT {n}×{d}', 'Objectif physiologique : Développer la puissance au-dessus de la PMA et la capacité anaérobie. Objectif aéro : Enchaîner des efforts de 30 s à 130 % FTP en TT, récupérations comprises.', 'Séries de 30 s dur / 30 s facile entièrement en TT : la puissance au-dessus de la PMA sans jamais quitter les prolongateurs. Pause redressée entre les séries.'),
('s_3030', 'en', '30/30 TT {n}×{d}', 'Physiological goal: Build power above VO2max and anaerobic capacity. Aero goal: String together 30 s efforts at 130% FTP in TT, recoveries included.', 'Sets of 30 s hard / 30 s easy entirely in TT: power above VO2max without ever leaving the extensions. Upright break between sets.'),
('s_3030', 'es', '30/30 TT {n}×{d}', 'Objetivo fisiológico: Desarrollar la potencia por encima del VO2max y la capacidad anaeróbica. Objetivo aero: Encadenar esfuerzos de 30 s al 130 % FTP en TT, recuperaciones incluidas.', 'Series de 30 s fuerte / 30 s suave totalmente en TT: potencia por encima del VO2max sin dejar nunca los acoples. Pausa erguido entre series.'),
('s_3030', 'it', '30/30 TT {n}×{d}', 'Obiettivo fisiologico: Sviluppare la potenza sopra il VO2max e la capacità anaerobica. Obiettivo aero: Concatenare sforzi di 30 s al 130 % FTP in TT, recuperi compresi.', 'Serie di 30 s forte / 30 s facile interamente in TT: potenza sopra il VO2max senza mai lasciare le protesi. Pausa eretto tra le serie.'),
('s_3030', 'de', '30/30 TT {n}×{d}', 'Physiologisches Ziel: Leistung über VO2max und anaerobe Kapazität entwickeln. Aero-Ziel: 30-s-Belastungen bei 130 % FTP in TT aneinanderreihen, Erholungen inklusive.', 'Serien 30 s hart / 30 s locker komplett in TT: Leistung über VO2max, ohne den Aufsatz je zu verlassen. Aufrechte Pause zwischen den Serien.'),
('s_3030', 'nl', '30/30 TT {n}×{d}', 'Fysiologisch doel: Vermogen boven VO2max en anaerobe capaciteit ontwikkelen. Aerodoel: Inspanningen van 30 s op 130 % FTP in TT aaneenrijgen, herstel inbegrepen.', 'Series van 30 s hard / 30 s rustig volledig in TT: vermogen boven VO2max zonder de opzetstukken ooit te verlaten. Pauze rechtop tussen de series.'),
('s_3030', 'pt', '30/30 TT {n}×{d}', 'Objetivo fisiológico: Desenvolver a potência acima do VO2max e a capacidade anaeróbia. Objetivo aero: Encadear esforços de 30 s a 130 % FTP em TT, recuperações incluídas.', 'Séries de 30 s forte / 30 s leve inteiramente em TT: potência acima do VO2max sem nunca sair do clipe. Pausa ereto entre as séries.'),
('s_3030', 'ja', '30/30 TT {n}×{d}', '生理学的目標：VO2max以上のパワーと無酸素能力を伸ばす。 エアロ目標：回復も含め、130 % FTPの30秒努力をTTで連続して行う。', '30秒ハード／30秒イージーを全てTTで：エアロバーを離れずにVO2max以上のパワー。セット間は起き上がって休憩。'),
('s_3030', 'tr', '30/30 TT {n}×{d}', 'Fizyolojik hedef: VO2max üstü gücü ve anaerobik kapasiteyi geliştirmek. Aero hedefi: Toparlanmalar dahil, TT''de %130 FTP''de 30 sn''lik eforları art arda yap.', 'Tamamen TT''de 30 sn sert / 30 sn kolay setler: uzatmaları hiç bırakmadan VO2max üstü güç. Setler arasında dik mola.'),
('s_relance', 'fr', 'Relances TT {n}×{d}', 'Objectif physiologique : Développer la capacité anaérobie et la répétition des accélérations. Objectif aéro : Relancer à 115-125 % FTP en restant en TT, comme après un virage ou une bosse.', 'Les relances coûtent cher en CLM et en triathlon : la plupart des coureurs se relèvent pour accélérer. Ici, chaque relance d''une minute se fait en TT, récupération redressée.'),
('s_relance', 'en', 'TT surges {n}×{d}', 'Physiological goal: Build anaerobic capacity and repeated accelerations. Aero goal: Surge at 115-125% FTP while staying in TT, like after a corner or a rise.', 'Surges are costly in TTs and triathlons: most riders sit up to accelerate. Here every one-minute surge is done in TT, recovery upright.'),
('s_relance', 'es', 'Cambios de ritmo TT {n}×{d}', 'Objetivo fisiológico: Desarrollar la capacidad anaeróbica y la repetición de aceleraciones. Objetivo aero: Acelerar al 115-125 % FTP sin salir del TT, como tras una curva o un repecho.', 'Los cambios de ritmo cuestan caro en CRI y triatlón: la mayoría se incorpora para acelerar. Aquí cada cambio de un minuto se hace en TT, recuperación erguido.'),
('s_relance', 'it', 'Rilanci TT {n}×{d}', 'Obiettivo fisiologico: Sviluppare la capacità anaerobica e la ripetizione delle accelerazioni. Obiettivo aero: Rilanciare al 115-125 % FTP restando in TT, come dopo una curva o uno strappo.', 'I rilanci costano cari in crono e triathlon: quasi tutti si rialzano per accelerare. Qui ogni rilancio di un minuto si fa in TT, recupero eretto.'),
('s_relance', 'de', 'TT-Antritte {n}×{d}', 'Physiologisches Ziel: Anaerobe Kapazität und wiederholte Beschleunigungen entwickeln. Aero-Ziel: Bei 115-125 % FTP antreten und in TT bleiben, wie nach einer Kurve oder Welle.', 'Antritte kosten im Zeitfahren und Triathlon viel: Die meisten richten sich zum Beschleunigen auf. Hier erfolgt jeder einminütige Antritt in TT, Erholung aufrecht.'),
('s_relance', 'nl', 'TT-versnellingen {n}×{d}', 'Fysiologisch doel: Anaerobe capaciteit en herhaalde versnellingen ontwikkelen. Aerodoel: Versnellen op 115-125 % FTP in TT, zoals na een bocht of heuveltje.', 'Versnellingen kosten veel in tijdritten en triatlons: de meeste renners komen overeind om te versnellen. Hier gebeurt elke versnelling van een minuut in TT, herstel rechtop.'),
('s_relance', 'pt', 'Retomadas TT {n}×{d}', 'Objetivo fisiológico: Desenvolver a capacidade anaeróbia e a repetição de acelerações. Objetivo aero: Retomar a 115-125 % FTP sem sair do TT, como depois de uma curva ou subida.', 'As retomadas custam caro no contrarrelógio e no triatlo: a maioria levanta para acelerar. Aqui cada retomada de um minuto é em TT, recuperação ereto.'),
('s_relance', 'ja', 'TT加速 {n}×{d}', '生理学的目標：無酸素能力と加速の反復力を伸ばす。 エアロ目標：カーブや登りの後のように、TTのまま115〜125 % FTPで加速する。', 'TTやトライアスロンでの加速は高くつきます。多くの選手は起き上がって加速します。ここでは1分の加速をすべてTTで、回復は起き上がって。'),
('s_relance', 'tr', 'TT atakları {n}×{d}', 'Fizyolojik hedef: Anaerobik kapasiteyi ve tekrarlı hızlanmaları geliştirmek. Aero hedefi: Bir viraj ya da yokuş sonrası gibi TT''de kalarak %115-125 FTP''de atak yap.', 'Ataklar zamana karşı ve triatlonda pahalıdır: çoğu sporcu hızlanmak için doğrulur. Burada her bir dakikalık atak TT''de, toparlanma dik.'),
('s_sprint', 'fr', 'Sprints TT {n}×{d}', 'Objectif physiologique : Développer la puissance maximale et l''explosivité. Objectif aéro : Sortir la puissance maximale sans quitter la position TT (sprints ≥ 160 % FTP).', 'Sprints assis en TT : les mains restent sur les prolongateurs, le buste reste bas, la force vient des jambes et du gainage. Récupération complète redressé entre les sprints.'),
('s_sprint', 'en', 'TT sprints {n}×{d}', 'Physiological goal: Build maximal power and explosiveness. Aero goal: Produce maximal power without leaving the TT position (sprints ≥ 160% FTP).', 'Seated TT sprints: hands stay on the extensions, torso stays low, the force comes from the legs and the core. Full recovery upright between sprints.'),
('s_sprint', 'es', 'Sprints TT {n}×{d}', 'Objetivo fisiológico: Desarrollar la potencia máxima y la explosividad. Objetivo aero: Sacar la potencia máxima sin dejar la posición TT (sprints ≥ 160 % FTP).', 'Sprints sentado en TT: las manos en los acoples, el tronco abajo, la fuerza viene de las piernas y del core. Recuperación completa erguido entre sprints.'),
('s_sprint', 'it', 'Sprint TT {n}×{d}', 'Obiettivo fisiologico: Sviluppare la potenza massima e l''esplosività. Obiettivo aero: Esprimere la potenza massima senza lasciare la posizione TT (sprint ≥ 160 % FTP).', 'Sprint seduti in TT: le mani restano sulle protesi, il busto basso, la forza viene da gambe e core. Recupero completo eretto tra gli sprint.'),
('s_sprint', 'de', 'TT-Sprints {n}×{d}', 'Physiologisches Ziel: Maximalleistung und Explosivität entwickeln. Aero-Ziel: Maximale Leistung bringen, ohne die TT-Position zu verlassen (Sprints ≥ 160 % FTP).', 'Sitzende TT-Sprints: Hände bleiben auf dem Aufsatz, Oberkörper tief, die Kraft kommt aus Beinen und Rumpf. Vollständige Erholung aufrecht zwischen den Sprints.'),
('s_sprint', 'nl', 'TT-sprints {n}×{d}', 'Fysiologisch doel: Maximaal vermogen en explosiviteit ontwikkelen. Aerodoel: Maximaal vermogen leveren zonder de TT-houding te verlaten (sprints ≥ 160 % FTP).', 'Zittende TT-sprints: handen blijven op de opzetstukken, romp laag, de kracht komt uit benen en core. Volledig herstel rechtop tussen de sprints.'),
('s_sprint', 'pt', 'Sprints TT {n}×{d}', 'Objetivo fisiológico: Desenvolver a potência máxima e a explosividade. Objetivo aero: Produzir a potência máxima sem sair da posição TT (sprints ≥ 160 % FTP).', 'Sprints sentado em TT: as mãos ficam no clipe, o tronco baixo, a força vem das pernas e do core. Recuperação completa ereto entre os sprints.'),
('s_sprint', 'ja', 'TTスプリント {n}×{d}', '生理学的目標：最大パワーと爆発力を伸ばす。 エアロ目標：TTポジションのまま最大パワーを出す（スプリント160 % FTP以上）。', 'TTでのシッティングスプリント：手はエアロバー、上体は低く、力は脚と体幹から。スプリントの間は起き上がって完全回復。'),
('s_sprint', 'tr', 'TT sprint {n}×{d}', 'Fizyolojik hedef: Maksimum gücü ve patlayıcılığı geliştirmek. Aero hedefi: TT pozisyonundan çıkmadan maksimum güç üret (sprintler ≥ %160 FTP).', 'TT''de oturarak sprint: eller uzatmalarda, gövde alçakta, güç bacaklardan ve gövdeden gelir. Sprintler arasında dik tam toparlanma.')
), wk(lang, p) AS (VALUES ('fr', 'S'), ('en', 'W'), ('es', 'S'), ('it', 'S'), ('de', 'W'), ('nl', 'W'), ('pt', 'S'), ('ja', 'W'), ('tr', 'H')
), ind(lang, many, one) AS (VALUES ('fr', 'Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Réussite : 1 passage en TT validé (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).'), ('en', 'Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Success: 1 TT block validated (≥ 95% of the block in TT, no exit of 20 s or more).'), ('es', 'Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Éxito: 1 tramo en TT validado (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).'), ('it', 'Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Riuscita: 1 tratto in TT validato (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).'), ('de', 'Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Erfolg: 1 TT-Abschnitt bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).'), ('nl', 'Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Geslaagd: 1 TT-stuk gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).'), ('pt', 'Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Sucesso: 1 trecho em TT validado (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).'), ('ja', '達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', '達成条件：TTブロック1本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。'), ('tr', 'Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Başarı: 1 TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).')
), s(skey, typ, week, n, d, minutes, k, aero, blocks, lc) AS (VALUES

('sprint_tt_12w_w1s1', 's_sprint', 1, '8', '15''''', 50, 9, 780, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 170.0, "power_end": 55.0, "duration_work": 15, "duration_recup": 165, "repetitions": 8, "position": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 660, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 770, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 2030, "key": "sprint_tt_12w_lc_start", "duration": 12}]'::jsonb),
('sprint_tt_12w_w1s2', 's_relance', 1, '6', '1''', 50, 7, 1380, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 120.0, "power_end": 60.0, "duration_work": 60, "duration_recup": 120, "repetitions": 6, "position": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 1020, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 770, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 950, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 1130, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 1310, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 1490, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 1670, "key": "sprint_tt_12w_lc_start", "duration": 12}]'::jsonb),
('sprint_tt_12w_w1s3', 's_3030', 1, '2', '8×30''''', 50, 33, 1860, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 130.0, "power_end": 50.0, "duration_work": 30, "duration_recup": 30, "repetitions": 8, "position": "prolongateurs", "position_recup": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 55.0, "duration_work": 240}, {"type": "FRAC", "unit": "% FTP", "power_start": 130.0, "power_end": 50.0, "duration_work": 30, "duration_recup": 30, "repetitions": 8, "position": "prolongateurs", "position_recup": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 900, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 630, "key": "sprint_tt_12w_lc_recup", "duration": 12}]'::jsonb),
('sprint_tt_12w_w1s4', 'e_cont', 1, '2', '20''', 61, 2, 2400, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 70.0, "power_end": 70.0, "duration_work": 1200, "duration_recup": 180, "repetitions": 2, "position": "prolongateurs", "position_recup": "cocottes"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 1200, "key": "sprint_tt_12w_lc_mid", "duration": 12}, {"at": 1800, "key": "sprint_tt_12w_lc_up", "duration": 10}, {"at": 1970, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 2580, "key": "sprint_tt_12w_lc_mid", "duration": 12}, {"at": 3180, "key": "sprint_tt_12w_lc_up", "duration": 10}]'::jsonb),
