('sprint_tt_12w_w12s1', 's_sprint', 12, '6', '15''''', 50, 7, 1110, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 170.0, "power_end": 55.0, "duration_work": 15, "duration_recup": 165, "repetitions": 6, "position": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 1020, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 770, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 1670, "key": "sprint_tt_12w_lc_start", "duration": 12}]'::jsonb),
('sprint_tt_12w_w12s2', 's_relance', 12, '5', '1''', 50, 6, 1500, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 115.0, "power_end": 60.0, "duration_work": 60, "duration_recup": 120, "repetitions": 5, "position": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 1200, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 770, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 950, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 1130, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 1310, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 1490, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 2100, "key": "sprint_tt_12w_lc_mid", "duration": 12}]'::jsonb),
('sprint_tt_12w_w12s3', 'e_cont', 12, '1', '40''', 55, 1, 2400, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 2400, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "sprint_tt_12w_lc_start", "duration": 12}, {"at": 1800, "key": "sprint_tt_12w_lc_mid", "duration": 12}]'::jsonb)
), built AS (
  SELECT s.*,
    (SELECT jsonb_object_agg(t.lang, wk.p || s.week || ' · ' || replace(replace(replace(replace(t.name, '{n}', s.n), '{d}', s.d), '{m}', s.minutes::text), ' 1×', ' '))
       FROM tpl t JOIN wk USING (lang) WHERE t.typ = s.typ) AS names,
    (SELECT jsonb_object_agg(t.lang, t.obj || ' ' || CASE WHEN s.k = 1 THEN i.one ELSE replace(i.many, '{k}', s.k::text) END)
       FROM tpl t JOIN ind i USING (lang) WHERE t.typ = s.typ) AS objs,
    (SELECT jsonb_object_agg(t.lang, t.info) FROM tpl t WHERE t.typ = s.typ) AS infos
  FROM s
)
INSERT INTO public.training_sessions (name, info, objectif, session_json, total_duration, is_test, live_comments, translations_json, aero_duration_sec)
SELECT b.skey || '_name', b.skey || '_info', b.skey || '_objectif',
  jsonb_build_object('nom', b.names ->> 'fr', 'infos', '', 'duration', b.minutes, 'UnitDisplay', '% FTP', 'blocks', b.blocks),
  b.minutes, false, b.lc,
  jsonb_build_object('name', b.names, 'objectif', b.objs, 'info', b.infos, 'live_comments', '{"sprint_tt_12w_lc_start": {"fr": "Passe en TT sur les prolongateurs : épaules relâchées, tiens jusqu''au bout du bloc.", "en": "Get into TT on the extensions: shoulders relaxed, hold until the end of the block.", "es": "Ponte en TT en los acoples: hombros relajados, aguanta hasta el final del bloque.", "it": "Mettiti in TT sulle protesi: spalle rilassate, tieni fino alla fine del blocco.", "de": "Ab in TT auf den Aufsatz: Schultern locker, bis zum Ende des Blocks halten.", "nl": "Ga in TT op de opzetstukken: schouders ontspannen, houd vol tot het einde van het blok.", "pt": "Vá para o TT no clipe: ombros relaxados, aguente até o fim do bloco.", "ja": "エアロバーでTTに：肩の力を抜き、ブロックの最後まで維持しよう。", "tr": "Uzatmalarda TT''ye geç: omuzlar gevşek, blok bitene kadar koru."}, "sprint_tt_12w_lc_up": {"fr": "Relève-toi et récupère. Prochain bloc en TT.", "en": "Sit up and recover. Next block in TT.", "es": "Incorpórate y recupera. Próximo bloque en TT.", "it": "Rialzati e recupera. Prossimo blocco in TT.", "de": "Aufrichten und erholen. Nächster Block in TT.", "nl": "Kom overeind en herstel. Volgend blok in TT.", "pt": "Levante o tronco e recupere. Próximo bloco em TT.", "ja": "上体を起こして回復。次のブロックはTTで。", "tr": "Doğrul ve toparlan. Sonraki blok TT''de."}, "sprint_tt_12w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}, "sprint_tt_12w_lc_recup": {"fr": "Récupère en TT : reste sur les prolongateurs, ton cerveau associe la position au repos.", "en": "Recover in TT: stay on the extensions, your brain links the position with rest.", "es": "Recupera en TT: sigue en los acoples, tu cerebro asocia la posición al descanso.", "it": "Recupera in TT: resta sulle protesi, il cervello associa la posizione al riposo.", "de": "Erhole dich in TT: Bleib auf dem Aufsatz, dein Gehirn verbindet die Position mit Ruhe.", "nl": "Herstel in TT: blijf op de opzetstukken, je brein koppelt de houding aan rust.", "pt": "Recupere em TT: fique no clipe, seu cérebro associa a posição ao descanso.", "ja": "TTで回復：エアロバーに乗ったまま。脳がこの姿勢を休息と結びつけます。", "tr": "TT''de toparlan: uzatmalarda kal, beynin pozisyonu dinlenmeyle ilişkilendirir."}}'::jsonb),
  b.aero
FROM built b
WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions ts WHERE ts.name = b.skey || '_name');

INSERT INTO public.training_plans (name_key, description_key, objective_key, duration_weeks, difficulty, plan_type, sessions_per_week, is_active, translations_json)
SELECT 'sprint_tt_12w_name', 'sprint_tt_12w_description', 'sprint_tt_12w_objective', 12, 'advanced', 'training', 4, true, '{"name": {"fr": "Puissance max en aéro 12 semaines", "en": "12-week max power in aero", "es": "Potencia máxima en aero 12 semanas", "it": "Potenza massima in aero 12 settimane", "de": "12 Wochen Maximalleistung in Aero", "nl": "12 weken maximaal vermogen in aero", "pt": "Potência máxima em aero 12 semanas", "ja": "12週間エアロでの最大パワー", "tr": "12 haftalık aero''da maksimum güç"}, "objective": {"fr": "Sprinter et relancer à plus de 110 % FTP sans quitter la position TT, jusqu''à 14 sprints, 14 relances et 5 séries de 30/30 par séance.", "en": "Sprint and surge above 110% FTP without leaving the TT position, up to 14 sprints, 14 surges and 5 sets of 30/30 per session.", "es": "Esprintar y acelerar por encima del 110 % FTP sin dejar la posición TT, hasta 14 sprints, 14 cambios de ritmo y 5 series de 30/30 por sesión.", "it": "Sprintare e rilanciare oltre il 110 % FTP senza lasciare la posizione TT, fino a 14 sprint, 14 rilanci e 5 serie di 30/30 per sessione.", "de": "Über 110 % FTP sprinten und antreten, ohne die TT-Position zu verlassen, bis zu 14 Sprints, 14 Antritte und 5 Serien 30/30 pro Einheit.", "nl": "Sprinten en versnellen boven 110 % FTP zonder de TT-houding te verlaten, tot 14 sprints, 14 versnellingen en 5 series 30/30 per sessie.", "pt": "Sprintar e retomar acima de 110 % FTP sem sair da posição TT, até 14 sprints, 14 retomadas e 5 séries de 30/30 por sessão.", "ja": "TTポジションのまま110 % FTP以上でスプリント・加速。1セッションで最大14本のスプリント、14本の加速、30/30を5セット。", "tr": "TT pozisyonundan çıkmadan %110 FTP üzerinde sprint ve atak; seans başına 14 sprint, 14 atak ve 5 set 30/30''a kadar."}, "description": {"fr": "12 semaines, trois cycles de 3 semaines de charge et 1 allégée, 3 à 4 séances de 50 à 90 minutes. Sprints assis de 15 à 20 s (170-180 % FTP), relances d''une minute (115-125 % FTP) et séries de 30/30 (130 % FTP), toujours en TT, plus une séance d''endurance TT par semaine jusqu''à 75 minutes d''affilée.", "en": "12 weeks, three cycles of 3 loading weeks and 1 lighter week, 3 to 4 sessions of 50 to 90 minutes. Seated 15 to 20 s sprints (170-180% FTP), one-minute surges (115-125% FTP) and 30/30 sets (130% FTP), always in TT, plus one TT endurance session a week up to 75 minutes in a row.", "es": "12 semanas, tres ciclos de 3 semanas de carga y 1 más ligera, 3 a 4 sesiones de 50 a 90 minutos. Sprints sentado de 15 a 20 s (170-180 % FTP), cambios de ritmo de un minuto (115-125 % FTP) y series 30/30 (130 % FTP), siempre en TT, más una sesión de resistencia TT por semana de hasta 75 minutos seguidos.", "it": "12 settimane, tre cicli di 3 settimane di carico e 1 di scarico, da 3 a 4 sessioni da 50 a 90 minuti. Sprint seduti da 15 a 20 s (170-180 % FTP), rilanci di un minuto (115-125 % FTP) e serie 30/30 (130 % FTP), sempre in TT, più una sessione di resistenza TT a settimana fino a 75 minuti di fila.", "de": "12 Wochen, drei Zyklen aus 3 Belastungswochen und 1 Entlastungswoche, 3 bis 4 Einheiten von 50 bis 90 Minuten. Sitzende Sprints von 15 bis 20 s (170-180 % FTP), einminütige Antritte (115-125 % FTP) und 30/30-Serien (130 % FTP), immer in TT, dazu eine TT-Ausdauereinheit pro Woche bis 75 Minuten am Stück.", "nl": "12 weken, drie cycli van 3 belastingsweken en 1 lichtere week, 3 tot 4 sessies van 50 tot 90 minuten. Zittende sprints van 15 tot 20 s (170-180 % FTP), versnellingen van een minuut (115-125 % FTP) en 30/30-series (130 % FTP), altijd in TT, plus één TT-duursessie per week tot 75 minuten aan één stuk.", "pt": "12 semanas, três ciclos de 3 semanas de carga e 1 mais leve, 3 a 4 sessões de 50 a 90 minutos. Sprints sentado de 15 a 20 s (170-180 % FTP), retomadas de um minuto (115-125 % FTP) e séries 30/30 (130 % FTP), sempre em TT, mais uma sessão de resistência TT por semana até 75 minutos seguidos.", "ja": "12週間、負荷3週＋軽め1週の3サイクル、50〜90分のセッションを週3〜4回。15〜20秒のシッティングスプリント（170〜180 % FTP）、1分の加速（115〜125 % FTP）、30/30（130 % FTP）を常にTTで。加えて週1回、最大75分連続のTT持久セッション。", "tr": "12 hafta, 3 yüklenme + 1 hafif haftadan oluşan üç döngü, haftada 50-90 dakikalık 3-4 seans. Oturarak 15-20 sn sprintler (%170-180 FTP), bir dakikalık ataklar (%115-125 FTP) ve 30/30 setleri (%130 FTP), hep TT''de; ayrıca haftada bir aralıksız 75 dakikaya kadar TT dayanıklılık seansı."}}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.training_plans WHERE name_key = 'sprint_tt_12w_name');

INSERT INTO public.plan_sessions (plan_id, training_session_id, week_number, session_number)
SELECT p.id, ts.id, v.week, v.num
FROM (VALUES (1, 1, 'sprint_tt_12w_w1s1_name'), (1, 2, 'sprint_tt_12w_w1s2_name'), (1, 3, 'sprint_tt_12w_w1s3_name'), (1, 4, 'sprint_tt_12w_w1s4_name'), (2, 1, 'sprint_tt_12w_w2s1_name'), (2, 2, 'sprint_tt_12w_w2s2_name'), (2, 3, 'sprint_tt_12w_w2s3_name'), (2, 4, 'sprint_tt_12w_w2s4_name'), (3, 1, 'sprint_tt_12w_w3s1_name'), (3, 2, 'sprint_tt_12w_w3s2_name'), (3, 3, 'sprint_tt_12w_w3s3_name'), (3, 4, 'sprint_tt_12w_w3s4_name'), (4, 1, 'sprint_tt_12w_w4s1_name'), (4, 2, 'sprint_tt_12w_w4s2_name'), (4, 3, 'sprint_tt_12w_w4s3_name'), (5, 1, 'sprint_tt_12w_w5s1_name'), (5, 2, 'sprint_tt_12w_w5s2_name'), (5, 3, 'sprint_tt_12w_w5s3_name'), (5, 4, 'sprint_tt_12w_w5s4_name'), (6, 1, 'sprint_tt_12w_w6s1_name'), (6, 2, 'sprint_tt_12w_w6s2_name'), (6, 3, 'sprint_tt_12w_w6s3_name'), (6, 4, 'sprint_tt_12w_w6s4_name'), (7, 1, 'sprint_tt_12w_w7s1_name'), (7, 2, 'sprint_tt_12w_w7s2_name'), (7, 3, 'sprint_tt_12w_w7s3_name'), (7, 4, 'sprint_tt_12w_w7s4_name'), (8, 1, 'sprint_tt_12w_w8s1_name'), (8, 2, 'sprint_tt_12w_w8s2_name'), (8, 3, 'sprint_tt_12w_w8s3_name'), (9, 1, 'sprint_tt_12w_w9s1_name'), (9, 2, 'sprint_tt_12w_w9s2_name'), (9, 3, 'sprint_tt_12w_w9s3_name'), (9, 4, 'sprint_tt_12w_w9s4_name'), (10, 1, 'sprint_tt_12w_w10s1_name'), (10, 2, 'sprint_tt_12w_w10s2_name'), (10, 3, 'sprint_tt_12w_w10s3_name'), (10, 4, 'sprint_tt_12w_w10s4_name'), (11, 1, 'sprint_tt_12w_w11s1_name'), (11, 2, 'sprint_tt_12w_w11s2_name'), (11, 3, 'sprint_tt_12w_w11s3_name'), (11, 4, 'sprint_tt_12w_w11s4_name'), (12, 1, 'sprint_tt_12w_w12s1_name'), (12, 2, 'sprint_tt_12w_w12s2_name'), (12, 3, 'sprint_tt_12w_w12s3_name')) AS v(week, num, session_name)
JOIN public.training_sessions ts ON ts.name = v.session_name
JOIN public.training_plans p ON p.name_key = 'sprint_tt_12w_name'
WHERE NOT EXISTS (SELECT 1 FROM public.plan_sessions ps WHERE ps.plan_id = p.id AND ps.training_session_id = ts.id);
